/* ==========================================================================
   VARIABLES & RESET
   ========================================================================== */
:root {
  --font-serif: 'Instrument Serif', Georgia, serif;
  --font-brand: 'Dancing Script', cursive;
  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;

  --color-white: #ffffff;
  --color-white-75: rgba(255, 255, 255, 0.75);
  --color-white-20: rgba(255, 255, 255, 0.2);
  --color-white-12: rgba(255, 255, 255, 0.12);
  --color-black: #08090c;
  --color-surface: #0e1015;
  --color-surface-alt: #13161d;
  --color-overlay-20: rgba(0, 0, 0, 0.20);
  --color-mobile-menu: rgba(8, 9, 12, 0.88);
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  background-color: var(--color-black);
  color: var(--color-white);
  font-family: var(--font-sans);
  -webkit-font-smoothing: antialiased;
}

body {
  min-height: 100vh;
  overflow-x: hidden;
  background-color: var(--color-black);
}

/* Foco visible accesible en todos los elementos interactivos */
a:focus-visible,
button:focus-visible,
input:focus-visible,
select:focus-visible {
  outline: 2px solid var(--color-white);
  outline-offset: 4px;
}

/* ==========================================================================
   HERO SECTION (COMPOSICIÓN PRINCIPAL)
   ========================================================================== */
.hero {
  position: relative;
  min-height: 100vh;
  min-height: 100svh;
  width: 100%;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  align-items: center;
  padding: 24px;
  color: var(--color-white);
  overflow: hidden;
}

@media (min-width: 768px) {
  .hero {
    padding: 36px 40px;
  }
}

@media (min-width: 1024px) {
  .hero {
    padding: 36px 48px;
  }
}

/* Video Background sin zoom, parallax ni movimiento artificial */
.hero__video-wrapper {
  position: absolute;
  inset: 0;
  z-index: 0;
  background-color: #101216;
}

.hero__video {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center center;
  display: block;
}

/* Capa negra sutil con sombreado para legibilidad sobre la fachada clara */
.hero__overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    180deg,
    rgba(8, 11, 16, 0.58) 0%,
    rgba(8, 11, 16, 0.34) 45%,
    rgba(8, 11, 16, 0.68) 100%
  );
  pointer-events: none;
}

/* Aviso discreto si el archivo de video falla */
.hero__video-fallback {
  position: absolute;
  bottom: 16px;
  left: 16px;
  z-index: 3;
  background: rgba(0, 0, 0, 0.72);
  border: 1px solid rgba(255, 255, 255, 0.25);
  color: var(--color-white-75);
  padding: 8px 12px;
  border-radius: 8px;
  font-size: 12px;
  font-family: var(--font-sans);
}

/* ==========================================================================
   TOPBAR DE CONTACTO DIRECTO (TELÉFONOS, WHATSAPP Y CORREO)
   ========================================================================== */
.topbar {
  background-color: #0b131e;
  border-bottom: 1px solid rgba(139, 197, 63, 0.28);
  font-size: 12px;
  padding: 8px 0;
  color: var(--color-white-75);
}

.topbar__inner {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
  text-align: center;
}

@media (min-width: 860px) {
  .topbar__inner {
    flex-direction: row;
    text-align: left;
  }
}

.topbar__group {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: 8px;
}

.topbar__dot {
  display: inline-block;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background-color: #8bc53f;
  margin-right: 6px;
  box-shadow: 0 0 8px rgba(139, 197, 63, 0.8);
}

.topbar__link {
  color: var(--color-white);
  text-decoration: none;
  transition: color 0.2s ease;
}

.topbar__link:hover {
  color: #8bc53f;
}

.topbar__social {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  color: #8bc53f;
  text-decoration: none;
  font-weight: 500;
  transition: opacity 0.2s ease;
}

.topbar__social:hover {
  opacity: 0.85;
}

.social-links {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 10px;
}

.social-links--center {
  justify-content: center;
}

.social-pill {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 8px 14px;
  border-radius: 9999px;
  background: rgba(139, 197, 63, 0.14);
  border: 1px solid rgba(139, 197, 63, 0.4);
  color: var(--color-white);
  font-size: 13px;
  font-weight: 500;
  text-decoration: none;
  transition: background-color 0.2s ease, transform 0.2s ease;
}

.social-pill:hover {
  background: rgba(139, 197, 63, 0.26);
  transform: translateY(-1px);
}

.topbar__sep {
  opacity: 0.35;
}

/* ==========================================================================
   NAVEGACIÓN
   ========================================================================== */
.navbar {
  position: relative;
  z-index: 10;
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.navbar__brand {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  color: var(--color-white);
  text-decoration: none;
  min-width: 0;
}

.navbar__logo-img {
  width: 42px;
  height: 42px;
  border-radius: 10px;
  object-fit: contain;
  background-color: #ffffff;
  padding: 2px;
  flex-shrink: 0;
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.25);
}

.navbar__brand-text {
  display: flex;
  flex-direction: column;
  line-height: 1;
}

.navbar__brand-script {
  font-family: var(--font-brand);
  font-weight: 400;
  font-size: 28px;
  line-height: 1;
  letter-spacing: 0.01em;
}

.navbar__brand-tag {
  font-family: var(--font-sans);
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: #8bc53f;
  margin-top: 3px;
}

.navbar__links {
  display: none;
  list-style: none;
  align-items: center;
  gap: 28px;
}

@media (min-width: 1024px) {
  .navbar__links {
    display: flex;
  }
}

.navbar__link {
  color: var(--color-white);
  text-decoration: none;
  font-family: var(--font-sans);
  font-size: 14px;
  font-weight: 400;
  letter-spacing: 0.02em;
  opacity: 0.9;
  transition: opacity 0.2s ease, color 0.2s ease;
}

.navbar__link:hover {
  opacity: 1;
  color: #8bc53f;
}

.navbar__actions {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-shrink: 0;
}

.btn--whatsapp-nav {
  display: none;
  padding: 9px 16px;
  font-size: 13px;
  font-weight: 500;
  color: #081204;
  background-color: #8bc53f;
  border-radius: 9999px;
  text-decoration: none;
}

@media (min-width: 640px) {
  .btn--whatsapp-nav {
    display: inline-flex;
  }
}

.btn.btn--nav-cta {
  display: none;
  padding: 10px 20px;
  font-size: 14px;
  font-weight: 400;
  color: var(--color-white);
  background: rgba(255, 255, 255, 0.14);
  border: 1px solid rgba(255, 255, 255, 0.3);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-radius: 9999px;
  text-decoration: none;
  transition: background-color 0.25s ease, border-color 0.25s ease;
}

.btn.btn--nav-cta:hover {
  background: rgba(255, 255, 255, 0.24);
  border-color: rgba(255, 255, 255, 0.5);
}

@media (min-width: 1024px) {
  .btn.btn--nav-cta {
    display: inline-flex;
  }
}

.navbar__toggle {
  display: inline-flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: 6px;
  width: 44px;
  height: 44px;
  background: rgba(255, 255, 255, 0.12);
  border: 1px solid rgba(255, 255, 255, 0.25);
  border-radius: 9999px;
  color: var(--color-white);
  cursor: pointer;
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
}

@media (min-width: 1024px) {
  .navbar__toggle {
    display: none;
  }
}

.navbar__toggle-line {
  width: 18px;
  height: 1.5px;
  background-color: var(--color-white);
  border-radius: 2px;
}

/* ==========================================================================
   MENÚ MÓVIL NEGRO TRANSLÚCIDO
   ========================================================================== */
.mobile-menu {
  position: fixed;
  inset: 0;
  z-index: 50;
  background-color: var(--color-mobile-menu);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
  padding: 24px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

.mobile-menu[hidden] {
  display: none;
}

.mobile-menu__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.mobile-menu__close {
  width: 44px;
  height: 44px;
  border-radius: 9999px;
  background: rgba(255, 255, 255, 0.1);
  border: 1px solid rgba(255, 255, 255, 0.25);
  color: var(--color-white);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
}

.mobile-menu__links {
  list-style: none;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 28px;
  margin: auto 0;
}

.mobile-menu__link {
  font-family: var(--font-serif);
  font-size: 38px;
  color: var(--color-white);
  text-decoration: none;
  letter-spacing: 0.01em;
}

.mobile-menu__footer {
  display: flex;
  justify-content: center;
  padding-bottom: 16px;
}

.mobile-menu__cta {
  width: 100%;
  max-width: 320px;
}

/* ==========================================================================
   CONTENIDO CENTRAL HERO
   ========================================================================== */
.hero__content {
  position: relative;
  z-index: 5;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  width: 100%;
  max-width: 1024px;
  margin: auto 0;
  padding: 40px 0;
}

/* Cápsula superior */
.hero__capsule {
  display: inline-flex;
  align-items: center;
  padding: 7px 18px;
  border-radius: 9999px;
  background: rgba(255, 255, 255, 0.12);
  border: 1px solid rgba(255, 255, 255, 0.28);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  font-family: var(--font-sans);
  font-size: 13px;
  font-weight: 400;
  letter-spacing: 0.04em;
  color: var(--color-white);
  margin-bottom: 24px;
}

/* H1: Instrument Serif 400, 2da línea cursiva, interlineado 0.95,
   48px móvil, 72-96px tablet, 120px escritorio, máx 1024px + brillo blanco suave */
.hero__title {
  font-family: var(--font-serif);
  font-weight: 400;
  font-size: 48px;
  line-height: 0.95;
  max-width: 1024px;
  color: var(--color-white);
  text-shadow:
    0 0 28px rgba(255, 255, 255, 0.42),
    0 0 64px rgba(255, 255, 255, 0.18);
  margin-bottom: 24px;
  overflow-wrap: break-word;
}

.hero__title em {
  font-family: var(--font-serif);
  font-style: italic;
  font-weight: 400;
}

@media (min-width: 768px) {
  .hero__title {
    font-size: clamp(72px, 10vw, 96px);
  }
}

@media (min-width: 1200px) {
  .hero__title {
    font-size: 120px;
  }
}

/* Subtítulo: 16–18px, máximo 576px, blanco al 75% */
.hero__subtitle {
  font-family: var(--font-sans);
  font-weight: 300;
  font-size: clamp(16px, 1.5vw, 18px);
  line-height: 1.6;
  max-width: 576px;
  color: var(--color-white-75);
  margin-bottom: 36px;
}

/* Botones redondos: apilados en móvil, en fila desde tablet */
.hero__buttons {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 14px;
  width: 100%;
  max-width: 320px;
}

@media (min-width: 640px) {
  .hero__buttons {
    flex-direction: row;
    justify-content: center;
    align-items: center;
    max-width: none;
    width: auto;
  }
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 15px 30px;
  border-radius: 9999px;
  font-family: var(--font-sans);
  font-size: 15px;
  font-weight: 400;
  letter-spacing: 0.01em;
  text-decoration: none;
  cursor: pointer;
  transition: transform 0.25s ease, background-color 0.25s ease, box-shadow 0.25s ease;
  border: 1px solid transparent;
}

.btn--solid {
  background-color: var(--color-white);
  color: #0a0b0e;
  font-weight: 500;
  box-shadow: 0 8px 28px rgba(255, 255, 255, 0.18);
}

.btn--solid:hover {
  background-color: rgba(255, 255, 255, 0.92);
  transform: translateY(-1px);
}

.btn--glass {
  background: rgba(255, 255, 255, 0.14);
  color: var(--color-white);
  border: 1px solid rgba(255, 255, 255, 0.34);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
}

.btn--glass:hover {
  background: rgba(255, 255, 255, 0.24);
  transform: translateY(-1px);
}

/* Pie del Hero: Desplázate */
.hero__footer {
  position: relative;
  z-index: 5;
  display: flex;
  justify-content: center;
  width: 100%;
}

.hero__scroll {
  display: inline-flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  color: var(--color-white-75);
  text-decoration: none;
  font-family: var(--font-sans);
  font-size: 12px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  transition: color 0.2s ease;
}

.hero__scroll:hover {
  color: var(--color-white);
}

.hero__scroll-indicator {
  width: 1px;
  height: 24px;
  background: linear-gradient(to bottom, rgba(255, 255, 255, 0.8), rgba(255, 255, 255, 0));
}

/* ==========================================================================
   ENTRADA ÚNICA DE OPACIDAD Y ASCENSO (12–24px durante 0.8–1s)
   ========================================================================== */
@keyframes heroEntrance {
  from {
    opacity: 0;
    transform: translateY(20px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.entrance-anim {
  animation: heroEntrance 0.9s cubic-bezier(0.22, 1, 0.36, 1) forwards;
}

@media (prefers-reduced-motion: reduce) {
  .entrance-anim {
    animation: none;
    opacity: 1;
    transform: none;
  }
  html {
    scroll-behavior: auto;
  }
}

/* ==========================================================================
   SECCIONES INMOBILIARIA SMART HOME & GALERÍA DE EDIFICIOS
   ========================================================================== */
.container {
  width: 100%;
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 24px;
}

@media (min-width: 768px) {
  .container {
    padding: 0 40px;
  }
}

@media (min-width: 1024px) {
  .container {
    padding: 0 48px;
  }
}

.section {
  position: relative;
  padding: 96px 0;
  background-color: var(--color-black);
  background-image:
    linear-gradient(180deg, rgba(8, 9, 12, 0.56) 0%, rgba(10, 15, 22, 0.36) 50%, rgba(8, 9, 12, 0.62) 100%),
    url('data:image/jpeg;base64,');
  background-size: cover;
  background-position: center;
  background-attachment: fixed;
  border-top: 1px solid rgba(139, 197, 63, 0.22);
}

.section--about {
  background-image:
    linear-gradient(180deg, rgba(8, 9, 12, 0.56) 0%, rgba(10, 16, 20, 0.34) 50%, rgba(8, 9, 12, 0.62) 100%),
    url('data:image/jpeg;base64,');
}

.section--showcase {
  background-image:
    linear-gradient(180deg, rgba(8, 9, 12, 0.54) 0%, rgba(10, 16, 22, 0.34) 50%, rgba(8, 9, 12, 0.62) 100%),
    url('data:image/jpeg;base64,');
}

.section--alt {
  background-color: var(--color-surface);
  background-image:
    linear-gradient(180deg, rgba(10, 13, 18, 0.58) 0%, rgba(10, 15, 22, 0.38) 50%, rgba(10, 13, 18, 0.65) 100%),
    url('data:image/jpeg;base64,');
  border-top: 1px solid rgba(139, 197, 63, 0.25);
  border-bottom: 1px solid rgba(139, 197, 63, 0.25);
}

.section--contact {
  background-image:
    linear-gradient(180deg, rgba(8, 9, 12, 0.54) 0%, rgba(10, 16, 22, 0.35) 50%, rgba(8, 9, 12, 0.64) 100%),
    url('data:image/jpeg;base64,');
}

@media (max-width: 767px) {
  .section,
  .section--about,
  .section--showcase,
  .section--alt,
  .section--contact {
    background-attachment: scroll;
  }
}

.section__header {
  max-width: 820px;
  margin-bottom: 64px;
  background: rgba(8, 11, 16, 0.62);
  border: 1px solid rgba(255, 255, 255, 0.16);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  padding: 28px 32px;
  border-radius: 22px;
  box-shadow: 0 16px 40px rgba(0, 0, 0, 0.35);
}

.section__eyebrow {
  display: inline-block;
  font-family: var(--font-sans);
  font-size: 12px;
  font-weight: 500;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--color-white-75);
  margin-bottom: 16px;
}

.section__title {
  font-family: var(--font-serif);
  font-weight: 400;
  font-size: clamp(36px, 5vw, 56px);
  line-height: 1.05;
  color: var(--color-white);
  margin-bottom: 20px;
}

.section__title em {
  font-style: italic;
}

.section__lead {
  font-family: var(--font-sans);
  font-weight: 300;
  font-size: 17px;
  line-height: 1.65;
  color: var(--color-white-75);
}

/* Ficha Oficial PRE-VENTA · Ubicación y Resumen de Venta (Alameda 5 Smart Living) */
.sales-summary-banner {
  display: grid;
  grid-template-columns: 1fr;
  border-radius: 24px;
  overflow: hidden;
  margin-bottom: 48px;
  border: 1px solid rgba(139, 197, 63, 0.35);
  box-shadow: 0 22px 54px rgba(0, 0, 0, 0.45);
}

@media (min-width: 960px) {
  .sales-summary-banner {
    grid-template-columns: 1.05fr 1.15fr;
  }
}

.sales-summary-banner__info {
  background: linear-gradient(145deg, rgba(16, 24, 58, 0.92) 0%, rgba(11, 16, 38, 0.95) 100%);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  padding: 32px 24px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 16px;
}

@media (min-width: 768px) {
  .sales-summary-banner__info {
    padding: 44px 40px;
  }
}

.sales-summary-banner__tag {
  font-family: var(--font-sans);
  font-size: 13px;
  font-weight: 500;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: #f97316;
}

.sales-summary-banner__title {
  font-family: var(--font-serif);
  font-weight: 400;
  font-size: clamp(32px, 4vw, 46px);
  line-height: 1.05;
  color: var(--color-white);
}

.sales-summary-banner__desc {
  font-size: 16px;
  font-weight: 300;
  line-height: 1.6;
  color: var(--color-white-75);
}

.sales-summary-banner__location {
  background: rgba(255, 255, 255, 0.06);
  border-left: 3px solid #8bc53f;
  padding: 14px 16px;
  border-radius: 0 12px 12px 0;
  font-size: 15px;
  line-height: 1.55;
  color: var(--color-white);
}

.sales-summary-banner__loc-label {
  display: block;
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: #8bc53f;
  margin-bottom: 4px;
}

.sales-summary-banner__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin-top: 8px;
}

.sales-summary-banner__actions .btn--whatsapp-nav {
  display: inline-flex;
  padding: 12px 24px;
  font-size: 14px;
  font-weight: 600;
}

.sales-summary-banner__grid {
  display: grid;
  grid-template-columns: 1fr;
  background: rgba(13, 18, 26, 0.82);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
}

@media (min-width: 560px) {
  .sales-summary-banner__grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

.sales-kpi-card {
  padding: 28px 24px;
  border-top: 1px solid rgba(255, 255, 255, 0.1);
  border-left: 1px solid rgba(255, 255, 255, 0.08);
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 10px;
}

@media (min-width: 768px) {
  .sales-kpi-card {
    padding: 36px 32px;
  }
}

.sales-kpi-card__num {
  font-family: var(--font-serif);
  font-size: clamp(32px, 3.5vw, 42px);
  line-height: 1.05;
  color: #f97316;
  font-weight: 400;
}

.sales-kpi-card__text {
  font-size: 14.5px;
  font-weight: 300;
  line-height: 1.6;
  color: var(--color-white-75);
}

/* Tarjetas de Edificios Smart Home */
.buildings-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 32px;
}

@media (min-width: 900px) {
  .buildings-grid {
